-- Synthetic TEST identities/catalog only. Stock is received and issued through the API driver.
SET NOCOUNT ON; SET XACT_ABORT ON;
IF DB_NAME()<>'HotelOpsCompactWorkdayTestP0261124' THROW 51991,'Exact isolated P0 database required.',1;
IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name='HotelOpsCompactSchema' AND CONVERT(varchar(20),value)='3.0.0') THROW 51992,'Validated P0 schema 3.0.0 required.',1;
IF ISJSON(@Credentials)<>1 THROW 51993,'Parameterized fixture credentials required.',1;
IF EXISTS(SELECT 1 FROM branches WHERE code IN ('P0_TEST_DVBV','P0_TEST_DVCT')) THROW 51994,'Fixture already exists; reuse its private manifest. Never reset it.',1;
DECLARE @actors TABLE(alias varchar(30),suffix varchar(4),role_code varchar(60),department_code varchar(30),username nvarchar(100),password_hash nvarchar(500));
INSERT @actors SELECT alias,suffix,roleCode,departmentCode,username,passwordHash FROM OPENJSON(@Credentials,'$.actors') WITH(alias varchar(30),suffix varchar(4),roleCode varchar(60),departmentCode varchar(30),username nvarchar(100),passwordHash nvarchar(500));
IF (SELECT COUNT(*) FROM @actors)<>20 OR EXISTS(SELECT 1 FROM @actors a WHERE NOT EXISTS(SELECT 1 FROM roles r WHERE r.code=a.role_code AND r.is_active=1)) THROW 51995,'Twenty fixture identities and migrated roles required.',1;
BEGIN TRANSACTION;
INSERT branches(code,name,timezone) VALUES('P0_TEST_DVBV',N'P0 TEST DVBV','Asia/Ho_Chi_Minh'),('P0_TEST_DVCT',N'P0 TEST DVCT','Asia/Ho_Chi_Minh');
INSERT departments(branch_id,code,name) SELECT b.branch_id,d.code,d.name FROM branches b CROSS JOIN (VALUES('HK',N'Buồng phòng'),('ENG',N'Bảo trì'),('FO',N'Lễ tân'),('STORE',N'Kho'),('OPS',N'Vận hành'))d(code,name) WHERE b.code IN ('P0_TEST_DVBV','P0_TEST_DVCT');
INSERT locations(branch_id,kind,code,name,floor_number) SELECT branch_id,'FLOOR','P0_F1',N'Tầng kiểm thử',1 FROM branches WHERE code IN ('P0_TEST_DVBV','P0_TEST_DVCT');
INSERT room_types(branch_id,code,name,capacity) SELECT branch_id,'P0_STANDARD',N'Hạng phòng kiểm thử',2 FROM branches WHERE code IN ('P0_TEST_DVBV','P0_TEST_DVCT');
INSERT rooms(branch_id,location_id,room_type_id,department_id,code,operational_status)
 SELECT b.branch_id,l.location_id,t.room_type_id,d.department_id,v.code,'DIRTY' FROM branches b JOIN locations l ON l.branch_id=b.branch_id JOIN room_types t ON t.branch_id=b.branch_id JOIN departments d ON d.branch_id=b.branch_id AND d.code='HK' CROSS JOIN(VALUES('P0_101'),('P0_102'),('P0_103'),('P0_104'))v(code) WHERE b.code IN ('P0_TEST_DVBV','P0_TEST_DVCT');
INSERT warehouses(branch_id,code,name,department_id) SELECT b.branch_id,'P0_MAIN',N'Kho kiểm thử duy nhất',d.department_id FROM branches b JOIN departments d ON d.branch_id=b.branch_id AND d.code='STORE' WHERE b.code IN ('P0_TEST_DVBV','P0_TEST_DVCT');
INSERT users(employee_code,username,full_name,password_hash,account_status,employment_status) SELECT username,username,N'P0 TEST '+alias+' '+suffix,password_hash,'ACTIVE','ACTIVE' FROM @actors;
INSERT memberships(user_id,branch_id,kind,valid_from,provenance) SELECT u.user_id,b.branch_id,'BRANCH_ACCESS',DATEADD(day,-1,SYSUTCDATETIME()),N'Isolated synthetic P0 fixture' FROM @actors a JOIN users u ON u.username=a.username JOIN branches b ON b.code='P0_TEST_'+a.suffix;
INSERT memberships(user_id,branch_id,department_id,kind,valid_from,provenance) SELECT u.user_id,b.branch_id,d.department_id,'EMPLOYMENT',DATEADD(day,-1,SYSUTCDATETIME()),N'Isolated synthetic P0 fixture' FROM @actors a JOIN users u ON u.username=a.username JOIN branches b ON b.code='P0_TEST_'+a.suffix JOIN departments d ON d.branch_id=b.branch_id AND d.code=a.department_code;
INSERT user_roles(user_id,role_id,branch_id,assigned_at) SELECT u.user_id,r.role_id,CASE WHEN a.role_code IN ('SYS_ADMIN','OWNER') THEN NULL ELSE b.branch_id END,DATEADD(day,-1,SYSUTCDATETIME()) FROM @actors a JOIN users u ON u.username=a.username JOIN roles r ON r.code=a.role_code JOIN branches b ON b.code='P0_TEST_'+a.suffix;
DECLARE @local datetime2=DATEADD(hour,7,SYSUTCDATETIME()),@start int;
SET @start=CASE WHEN DATEPART(hour,@local)*60+DATEPART(minute,@local)<30 THEN 0 WHEN DATEPART(hour,@local)*60+DATEPART(minute,@local)>990 THEN 960 ELSE DATEPART(hour,@local)*60+DATEPART(minute,@local)-30 END;
INSERT workday_shifts(branch_id,department_id,role_id,name,start_minute,end_minute,capacity) SELECT DISTINCT b.branch_id,d.department_id,r.role_id,N'Ca P0 TEST',@start,@start+480,10 FROM @actors a JOIN branches b ON b.code='P0_TEST_'+a.suffix JOIN departments d ON d.branch_id=b.branch_id AND d.code=a.department_code JOIN roles r ON r.code=a.role_code WHERE a.role_code NOT IN ('SYS_ADMIN','OWNER');
INSERT workday_assignments(shift_id,user_id,work_date,created_by) SELECT s.shift_id,u.user_id,CONVERT(date,@local),u.user_id FROM @actors a JOIN users u ON u.username=a.username JOIN branches b ON b.code='P0_TEST_'+a.suffix JOIN roles r ON r.code=a.role_code JOIN workday_shifts s ON s.branch_id=b.branch_id AND s.role_id=r.role_id;
INSERT reference_values(kind,code,name) VALUES('UOM','P0_TEST_UNIT',N'Đơn vị kiểm thử');
DECLARE @unit bigint=SCOPE_IDENTITY();
INSERT inventory_items(code,name,base_unit_id,description) SELECT code,name,@unit,N'Synthetic TEST catalog; stock only through posted physical-receipt simulation' FROM(VALUES('P0_FILL_BRUSH',N'Bàn chải'),('P0_FILL_PASTE',N'Kem đánh răng'),('P0_FILL_SHAMPOO',N'Dầu gội'),('P0_FILL_WASH',N'Sữa tắm'),('P0_FILL_WATER',N'Nước uống'),('P0_FILL_PAPER',N'Giấy vệ sinh'),('P0_FILL_TOWEL',N'Khăn tắm'),('P0_FILL_FACE',N'Khăn mặt'),('P0_DURABLE_KETTLE',N'Ấm đun'))i(code,name);
INSERT assets(branch_id,asset_code,name,room_id,department_id,condition_code) SELECT b.branch_id,'P0_AC_'+b.code,N'Điều hòa kiểm thử',r.room_id,d.department_id,'GOOD' FROM branches b JOIN rooms r ON r.branch_id=b.branch_id AND r.code='P0_101' JOIN departments d ON d.branch_id=b.branch_id AND d.code='HK' WHERE b.code IN ('P0_TEST_DVBV','P0_TEST_DVCT');
-- A draft request establishes the receiving room; approval, issue and stock posting remain real API operations.
INSERT inventory_documents(branch_id,document_no,kind,status,department_id,source_warehouse_id,receiving_room_id,reason,created_by)
 SELECT b.branch_id,'P0_INITIAL_ROOM_'+b.code,'MATERIAL_REQUEST','DRAFT',d.department_id,w.warehouse_id,r.room_id,N'Synthetic TEST initial room equipment',u.user_id FROM branches b JOIN departments d ON d.branch_id=b.branch_id AND d.code='HK' JOIN warehouses w ON w.branch_id=b.branch_id JOIN rooms r ON r.branch_id=b.branch_id AND r.code='P0_101' JOIN @actors a ON b.code='P0_TEST_'+a.suffix AND a.alias='hk' JOIN users u ON u.username=a.username WHERE b.code IN ('P0_TEST_DVBV','P0_TEST_DVCT');
COMMIT;
SELECT JSON_QUERY((SELECT b.branch_id branchId,b.code,w.warehouse_id warehouseId,JSON_QUERY((SELECT d.department_id departmentId,d.code FROM departments d WHERE d.branch_id=b.branch_id FOR JSON PATH)) departments,JSON_QUERY((SELECT r.room_id roomId,r.code,r.operational_status status FROM rooms r WHERE r.branch_id=b.branch_id FOR JSON PATH)) rooms,(SELECT asset_id FROM assets WHERE branch_id=b.branch_id AND asset_code='P0_AC_'+b.code) assetId,(SELECT document_id FROM inventory_documents WHERE document_no='P0_INITIAL_ROOM_'+b.code) initialRoomRequestId FROM branches b JOIN warehouses w ON w.branch_id=b.branch_id WHERE b.code IN ('P0_TEST_DVBV','P0_TEST_DVCT') FOR JSON PATH)) branches,
 JSON_QUERY((SELECT a.alias,a.suffix,a.username,u.user_id userId,a.role_code roleCode,b.branch_id branchId,d.department_id departmentId,s.assignment_id assignmentId,CAST('' AS xml).value('xs:base64Binary(sql:column("s.row_version"))','varchar(100)') rowVersion FROM @actors a JOIN users u ON u.username=a.username JOIN branches b ON b.code='P0_TEST_'+a.suffix JOIN departments d ON d.branch_id=b.branch_id AND d.code=a.department_code LEFT JOIN workday_assignments s ON s.user_id=u.user_id FOR JSON PATH)) actors,
 JSON_QUERY((SELECT item_id itemId,code,name,base_unit_id unitId FROM inventory_items WHERE code LIKE 'P0_FILL_%' OR code='P0_DURABLE_KETTLE' FOR JSON PATH)) items FOR JSON PATH,WITHOUT_ARRAY_WRAPPER;
